WITH with_windows AS (SELECT *, AVG(salary) OVER (PARTITION BY manager_id) AS manager_id_avg_salary, AVG(salary) OVER (PARTITION BY level ORDER BY hire_date, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS salary_avg_5_prior, ROW_NUMBER() OVER (PARTITION BY YEAR(hire_date), manager_id ORDER BY salary DESC, id) AS row_seq FROM employees) SELECT id, email, dept_id, manager_id, job_title, salary, is_remote, level, CASE WHEN level RLIKE '^(L4|L2)$' THEN 'GROUP_A' WHEN level RLIKE '^(L1|L3)$' THEN 'GROUP_B' ELSE 'OTHER_ZONE' END AS level_zone FROM with_windows ORDER BY id NULLS LAST;
